preConditionHook:
// Entry & Exit Confessions #12 (RSI Trigger), verbatim.
// MultiWalk's WFSafe_RSI, copied from RsiBelowThreshold (the bit-exact
// reference; EL_WFSafeRsi_Probe.txt, scripts/rsi_replica.py): TS's RSI with
// SF = 1/Length recomputed every bar, NO re-seed on a length change, seeded at
// the study's first calculated bar with NetChgAvg = (Price - Price[Length]) /
// Length and a fresh Average(AbsValue(Price - Price[1]), Length), followed by
// EMA-form updates. `TotChgAvg <> 0` carries the EL tolerance. sfRsi and
// chgRatio are declared locals so they take the placement prefix.
sfRsi = 1 / rsiLength;
if (ctx.CurrentBar() == 1) {
    netChgAvg = (close[0] - close[(int)rsiLength]) / rsiLength;
    double totChg = 0.0;
    for (int i = 0; i < (int)rsiLength; ++i) {
        totChg += std::fabs(close[i] - close[i + 1]);
    }
    totChgAvg = totChg / rsiLength;
} else {
    double change = close[0] - close[1];
    netChgAvg = netChgAvg + sfRsi * (change - netChgAvg);
    totChgAvg = totChgAvg + sfRsi * (std::fabs(change) - totChgAvg);
}
chgRatio = 0.0;
if (el_ne(totChgAvg, 0.0)) chgRatio = netChgAvg / totChgAvg;
rsiVal = 50 * (chgRatio + 1);
// EL's Average recomputes from scratch every bar (CloseAboveAverage is the
// reference); the close series has real history, so no warm-up mirroring.
avgClose = 0.0;
for (int i = 0; i < (int)xBars; ++i) {
    avgClose += close[i];
}
avgClose /= (int)xBars;
